// The game's levels, in play order: every pack's levels one after the other
// (CANGUPA-56). The old flat list of 50 levels is gone; these are the same
// levels apps/app/src/game/packs.ts holds, generated by tools/gen-packs.js.
//
// A level's index here is what saved progress, the unlock rule and the stats
// screen all count by, so it runs straight on from one pack to the next:
// pack 1 is indices 0-49, pack 2 is 50-99, and so on. Finishing a pack's last
// level opens the next pack's first.
import { type Level } from './board';
import { PACKS } from './packs';

export const LEVELS: readonly Level[] = PACKS.flatMap((pack) => pack.levels);

// How many levels each pack has, in pack order: the levels screen turns a
// level index into a pack by walking these.
export const PACK_SIZES: readonly number[] = PACKS.map((pack) => pack.levels.length);
